-- Wrap auth.uid()/current_setting() in RLS policy predicates in (select ...) so
-- Postgres evaluates each once per statement (an InitPlan) instead of once per row --
-- the Supabase-documented RLS perf pattern. Covers USING and WITH CHECK. Predicate-
-- equivalent (row visibility unchanged). Generated by 'pgrls fix --rule PERF001'
-- (pgrls 0.44.0) and verified on Postgres 16 (PERF001 -> 0).

-- [PERF001] Wrap auth function call(s) in policy 'Users can read own profile' on public.profiles so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can read own profile" ON public.profiles
    USING ((SELECT auth.uid()) = id);

-- [PERF001] Wrap auth function call(s) in policy 'Users can update own profile' on public.profiles so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can update own profile" ON public.profiles
    USING ((SELECT auth.uid()) = id)
    WITH CHECK ((SELECT auth.uid()) = id);

-- [PERF001] Wrap auth function call(s) in policy 'Owner can delete their shared mcp' on public.shared_mcp_configs so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Owner can delete their shared mcp" ON public.shared_mcp_configs
    USING (owner_id = (SELECT auth.uid()));

-- [PERF001] Wrap auth function call(s) in policy 'Owner can update their shared mcp' on public.shared_mcp_configs so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Owner can update their shared mcp" ON public.shared_mcp_configs
    USING (owner_id = (SELECT auth.uid()));

-- [PERF001] Wrap auth function call(s) in policy 'Owner or team member can read mcp' on public.shared_mcp_configs so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Owner or team member can read mcp" ON public.shared_mcp_configs
    USING (owner_id = (SELECT auth.uid()) OR team_id IN (SELECT team_members.team_id FROM team_members WHERE team_members.user_id = auth.uid() AND team_members.status = CAST('active' AS text)));

-- [PERF001] Wrap auth function call(s) in policy 'Pro/Team users can create shared mcp' on public.shared_mcp_configs so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Pro/Team users can create shared mcp" ON public.shared_mcp_configs
    WITH CHECK (owner_id = (SELECT auth.uid()) AND user_has_plan((SELECT auth.uid()), ARRAY[CAST('pro' AS text), CAST('team' AS text)]));

