-- [PERF001] Wrap auth function call(s) in policy 'Invitee can accept invitation' on public.team_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Invitee can accept invitation" ON public.team_members
    USING ((user_id = (SELECT auth.uid()) OR email = _current_user_email()) AND status = CAST('pending' AS text));

-- [PERF001] Wrap auth function call(s) in policy 'Invitee can decline own pending invite' on public.team_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
