    USING (status = CAST('pending' AS text) AND (user_id = (SELECT auth.uid()) OR email = _current_user_email()));

-- [PERF001] Wrap auth function call(s) in policy 'Owner can manage member rows' on public.team_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Owner can manage member rows" ON public.team_members
    USING (user_id = (SELECT auth.uid()) OR team_id IN (SELECT _user_owned_team_ids() AS _user_owned_team_ids));

-- [PERF001] Wrap auth function call(s) in policy 'Team leader can delete members' on public.team_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Team leader can delete members" ON public.team_members
    USING (team_id IN (SELECT team_members_1.team_id FROM team_members AS team_members_1 WHERE team_members_1.user_id = auth.uid() AND team_members_1.role = CAST('leader' AS text) AND team_members_1.status = CAST('active' AS text)) AND user_id <> (SELECT teams.owner_id FROM teams WHERE teams.id = team_members.team_id) AND user_id <> (SELECT auth.uid()));

-- [PERF001] Wrap auth function call(s) in policy 'Team members can read member list' on public.team_members so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Team members can read member list" ON public.team_members
    USING (user_id = (SELECT auth.uid()) OR email = _current_user_email() OR team_id IN (SELECT _user_active_team_ids() AS _user_active_team_ids) OR team_id IN (SELECT _user_owned_team_ids() AS _user_owned_team_ids));

